import{_ as a,o as t,c as o,a3 as i}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"固体反馈/整流","description":"","frontmatter":{"translationSource":{"title":"固体反馈/整流","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pBac1odUlClSBZoxZFu995","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/solid-item-feedback-flow-regularization"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/solid-item-feedback-flow-regularization"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/solid-item-feedback-flow-regularization"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/solid-item-feedback-flow-regularization"}]]},"headers":[],"relativePath":"zh/solid-item-feedback-flow-regularization.md","filePath":"zh/page-pBac1odUlClSBZoxZFu995.md"}'),l={name:"zh/solid-item-feedback-flow-regularization.md"};function r(d,e,s,n,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="固体反馈-整流" aria-hidden="true"></span><h1 id="固体反馈-整流" tabindex="-1">固体反馈/整流 <a class="header-anchor" href="#固体反馈-整流" aria-label="Permalink to &quot;固体反馈/整流&quot;">​</a></h1><blockquote><p>源页面 ID：<code>pBac1odUlClSBZoxZFu995</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pBac1odUlClSBZoxZFu995" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>谁开的这页：kokobird</p><p>为何：存一下未来科技佬的固体反馈蓝图，有空再详细琢磨以及放到合适的地方</p><p><a href="https://beta.enka.network/endfield/aic/?id=w2N2A5u7H2t0w2" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=w2N2A5u7H2t0w2</a></p><p>原理：协议箱首先进粉末，然后粉末形成循环；末尾的箱子虽然会进息壤，但是只会先出位置靠前的粉末。等息壤填满中间段缓存后，溢流和粉末汇流，此时箱子中应该已经填满粉末和息壤，汇流后息壤在门口等待，同时把粉末阻断在外面。剩余一条路径只剩半速粉末，因此箱子中粉末逐渐减少，最终息壤开始满速输出，直到中间的缓存排尽为止</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e388e8752d96a065.q90-3b18762ff61841a8.webp" alt="固体反馈/整流"></p><p>全君出击固体整流器，左侧源石粉末和致密粉末形成周期钟，源石粉末进入源石循环，会在循环中卡出一个空位，这个空位会被砂叶粉末进入。原本砂叶粉末循环刚好有三个，堵住右侧碳块输出，砂叶粉末进入一个后会让碳块满速输出，然后再重新关上。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1673635fa5ddc2f1.q90-f450d54f97905834.webp" alt="固体反馈/整流"></p></div>',1)])])}const k=a(l,[["render",r]]);export{h as __pageData,k as default};
